/* 直接用 index.html 跑：真实 JSONP + 真实 localStorage + 真实库，输出面板实际会渲染的内容 */
const fs = require('fs'), path = require('path'), vm = require('vm');
const https = require('https');
const dir = '分析产出/持仓面板';
const BASES = ['https://cdn.bootcdn.net/ajax/libs/sql.js/1.13.0/', 'https://cdn.staticfile.org/sql.js/1.13.0/'];

function httpGet(u, asBuffer) {
  return new Promise((res, rej) => {
    const r = https.get(u, { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://data.eastmoney.com/' } }, x => {
      if (x.statusCode >= 300 && x.statusCode < 400 && x.headers.location) { x.resume(); return httpGet(x.headers.location, asBuffer).then(res, rej); }
      const c = []; x.on('data', d => c.push(d));
      x.on('end', () => res(asBuffer ? Buffer.concat(c) : Buffer.concat(c).toString('utf8')));
    });
    r.on('error', rej); r.setTimeout(30000, () => r.destroy(new Error('timeout ' + u)));
  });
}

// ---- 最小但真实的 DOM ----
const registry = {};
function mkEl(tag) {
  const e = {
    tagName: (tag || 'div').toUpperCase(), id: '', className: '', innerHTML: '', textContent: '', value: '',
    placeholder: '', title: '', checked: false, options: [], selectedIndex: 0,
    style: {}, dataset: {},
    classList: { _s: new Set(), toggle(c){ this._s.has(c)?this._s.delete(c):this._s.add(c); }, add(c){ this._s.add(c); }, remove(c){ this._s.delete(c); }, contains(c){ return this._s.has(c); } },
    children: [], _handlers: {},
    addEventListener(t, f){ (this._handlers[t] = this._handlers[t] || []).push(f); },
    removeEventListener(){}, setAttribute(k, v){ this[k] = v; }, getAttribute(k){ return this[k]; },
    appendChild(c){ this.children.push(c); return c; }, removeChild(c){ this.children = this.children.filter(x => x !== c); },
    remove(){}, click(){ (this._handlers.click||[]).forEach(f => f({ target: this })); },
    querySelector(){ return null; }, querySelectorAll(){ return []; }, closest(){ return null; },
    focus(){}, blur(){}, getBoundingClientRect(){ return { top:0,left:0,width:100,height:20 }; }
  };
  return e;
}
function $(id) {
  if (!registry[id]) { registry[id] = mkEl('div'); registry[id].id = id; }
  return registry[id];
}
const document = {
  getElementById: id => $(id),
  querySelector: s => $(String(s).replace(/^#/, '')),
  querySelectorAll: () => [],
  addEventListener: () => {},
  createElement: t => mkEl(t),
  head: { appendChild: s => { if (s && s.src) loadScriptInto(s.src); } },
  body: { appendChild: () => {} },
  visibilityState: 'visible'
};

// localStorage（带真实 key 缓存能力）
const _ls = {};
const localStorage = {
  getItem: k => (k in _ls ? _ls[k] : null),
  setItem: (k, v) => { _ls[k] = String(v); },
  removeItem: k => { delete _ls[k]; }
};

const sandbox = {
  console, Date, Math, Number, String, Object, Array, JSON, isNaN, isFinite, parseFloat, parseInt, RegExp, Error, Promise,
  require, __dirname: process.cwd(), __filename: path.join(process.cwd(), '_live.js'),
  Uint8Array, Int8Array, Uint32Array, Int32Array, Float64Array, ArrayBuffer, WebAssembly, TextDecoder, TextEncoder, Buffer, process,
  setTimeout, clearTimeout, setInterval: () => 0, clearInterval() {},
  atob: s => Buffer.from(s, 'base64').toString('binary'),
  confirm: () => true, alert: () => {},
  indexedDB: { open: () => ({}) },
  localStorage,
  document,
  location: { search: '' },
  FileReader: function () {}, Blob: function () {},
  URL: { createObjectURL: () => '', revokeObjectURL() {} },
  fetch: u => httpGet(u, false).then(b => ({
    ok: true, status: 200,
    json: () => Promise.resolve(JSON.parse(b)),
    text: () => Promise.resolve(b),
    arrayBuffer: () => Promise.resolve(Buffer.from(b, 'utf8').buffer)
  }))
};
sandbox.window = sandbox; sandbox.self = sandbox; sandbox.globalThis = sandbox;
vm.createContext(sandbox);

let loadScriptInto;

(async () => {
  // 1) sql.js 引擎
  let SQL = null;
  for (const base of BASES) {
    try {
      const wasm = await httpGet(base + 'sql-wasm.wasm', true);
      if (wasm[0] !== 0x00 || wasm[1] !== 0x61) throw new Error('not wasm');
      const s0 = { console, require, __dirname: process.cwd(), __filename: path.join(process.cwd(), '_e.js'),
        Uint8Array, Buffer, process, setTimeout, clearTimeout, WebAssembly,
        document: { getElementById: () => mkEl('div'), querySelector: () => mkEl('div'), querySelectorAll: () => [], addEventListener(){}, createElement: () => mkEl('div'), head:{appendChild(){}}, body:{appendChild(){}} } };
      vm.createContext(s0);
      vm.runInContext((await httpGet(base + 'sql-wasm.js', false)), s0);
      SQL = await s0.initSqlJs({ wasmBinary: new Uint8Array(wasm) });
      break;
    } catch (e) {}
  }
  if (!SQL) throw new Error('CDN 失败');

  const html = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');
  const SCHEMA = html.match(/const SCHEMA = `([\s\S]*?)`;/)[1];

  // 读真实库
  const dbReal = new SQL.Database(new Uint8Array(fs.readFileSync(path.join(dir, 'holding.sqlite'))));
  const dbBytes = dbReal.export();

  // 2) 真实 JSONP：拦截 <script src> 下载并以脚本方式执行
  loadScriptInto = src => {
    httpGet(src, false).then(body => {
      try { vm.runInContext(body, sandbox); } catch (e) { console.log('  [jsonp err]', src.slice(0, 60), e.message); }
    }).catch(e => console.log('  [jsonp net]', src.slice(0, 60), e.message));
  };

  // 3) 预置：让 openDbFromBytes 拿得到库（模拟 File System Access 句柄）
  const main = html.match(/<script>\n\(function \(\) \{\n'use strict';\n\n\/\* =+ 常量[\s\S]*?<\/script>/)[0].replace(/^<script>\n/,'').replace(/<\/script>$/,'');
  vm.runInContext(main, sandbox);
  const P = sandbox.__PANEL__;
  if (!P) throw new Error('__PANEL__ 未就绪');

  const db = new SQL.Database(new Uint8Array(dbBytes));
  P._setDb(db);
  P._readState();

  console.log('=== 面板读库后状态 ===');
  console.log('库内 cfg targets =', P.S.targets ? P.S.targets.length : '(n/a)');
  console.log('持仓标的数 =', P.rowsNow().filter(r => r.shares > 0).length);

  // 4) 真实行情（腾讯）
  const tgts = P.rowsNow();
  const codes = tgts.map(r => r.code);
  console.log('目标池 =', codes.length, '只');
  const q = await httpGet('https://qt.gtimg.cn/q=' + codes.map(c => (c[0]==='6'?'sh':'sz')+c).join(','), true);
  const qtxt = new TextDecoder('gbk').decode(q);
  const pxObj = {};
  qtxt.split(';').forEach(seg => {
    const m = seg.match(/v_(\w\w)(\d{6})="([^"]*)"/);
    if (!m) return;
    const f = m[3].split('~');
    if (f[3] && +f[3] > 0) pxObj[m[2]] = { price: +f[3], prev: +f[4], chg: 0, name: f[1], at: Date.now() };
  });
  P.S.px = pxObj;
  P.S.active = 'ALL';
  console.log('行情取到 =', Object.keys(pxObj).length, '只');

  // 5) 真实安全边际指标（走面板自己的 loadMarginMetrics，JSONP 已打通）
  console.log('\n=== 拉安全边际指标（面板原生路径） ===');
  const cnt = await P.loadMarginMetrics(true);
  console.log('margin =', cnt, '条');
  await new Promise(r => setTimeout(r, 3000));
  console.log('再次统计 margin =', P._marginCount());

  // 6) 渲染并打印面板实际输出
  const inSel = $( 'inPlanAmount' );
  inSel.tagName = 'SELECT';
  inSel.value = '5000';
  P.render();

  const strip = s => String(s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  console.log('\n========== 面板实际显示 ==========');
  console.log('[标题]', strip($('planHead').textContent || $('planHead').innerHTML));
  const bodyHtml = $('planBody').innerHTML;
  console.log('[推荐表]', bodyHtml ? strip(bodyHtml).slice(0, 400) : '(空)');
  console.log('[说明]', strip($('planNote').textContent || $('planNote').innerHTML).slice(0, 500));
  console.log('\n[预警]', strip($('alertBox').innerHTML).slice(0, 300));
})().catch(e => { console.error('ERR', e.message); console.error(e.stack); process.exit(1); });

