  plan.skipped.forEach(x => L.push('    ✗ ' + x.r.name + '：' + x.why));

  const msg = L.join('\n');
  try { console.log(msg); } catch (e) {}
  // 弹窗展示（可复制）
  const w = window.open('', '_blank');
